-- English migration, step 4: M6-M9 exercises + lessons content + lesson titles. Idempotent.

update exercises set content = '{"isCode": false, "prompt": "Warm-up (M5): you need to call an embeddings API 5,000 times. Which two asyncio primitives would you use, and what''s each one for?", "modelAnswer": "gather to fire the calls concurrently and collect results in order, and Semaphore to limit how many are in flight at once so you don''t exceed the API''s rate limit.", "meta": {"difficulty": 1, "interview": false, "concepts": ["gather", "Semaphore"], "recuerda_de": "m5-async"}}'::jsonb where id = 'm6-e1';
update exercises set content = '{"prompt": "Sliding-window chunking. What does this print? Count the overlap carefully.", "code": "def chunks(tokens, size, overlap):\n    step = size - overlap\n    return [tokens[i:i+size] for i in range(0, len(tokens), step)]\n\nt = list(''ABCDEFGH'')\nfor c in chunks(t, 4, 1):\n    print(''''.join(c))", "expected_output": "ABCD\nDEFG\nGH", "explanation": "With size 4 and overlap 1 the step is 3: chunks start at 0, 3, and 6. The last one comes up short (GH) because there are no more tokens. That short final chunk is a real decision: drop it, pad it, or merge it with the previous one.", "meta": {"difficulty": 2, "interview": true, "concepts": ["chunking", "overlap"]}}'::jsonb where id = 'm6-e2';
update exercises set content = '{"prompt": "Cosine similarity by hand. What does this print? Think about the geometry before calculating.", "code": "import math\n\ndef cos(a, b):\n    dot = sum(x*y for x, y in zip(a, b))\n    na = math.sqrt(sum(x*x for x in a))\n    nb = math.sqrt(sum(y*y for y in b))\n    return round(dot / (na * nb), 2)\n\nprint(cos([1, 0], [1, 0]))\nprint(cos([1, 0], [0, 1]))\nprint(cos([1, 0], [5, 0]))\nprint(cos([1, 1], [-1, -1]))", "expected_output": "1.0\n0.0\n1.0\n-1.0", "explanation": "Cosine measures the angle, not the length: [1,0] and [5,0] point the same way, so they give 1.0. Perpendicular vectors give 0, and opposite ones give -1. That''s why embeddings are usually normalized: only direction matters.", "meta": {"difficulty": 2, "interview": true, "concepts": ["cosine similarity", "normalization"]}}'::jsonb where id = 'm6-e3';
update exercises set content = '{"prompt": "Order the lines to implement top-k search: given a query vector and an index {id: vector}, return the k most similar ids.", "lines": ["def top_k(query, index, k, sim):", "    scores = [(sim(query, v), id_) for id_, v in index.items()]", "    scores.sort(reverse=True)", "    return [id_ for _, id_ in scores[:k]]"], "meta": {"difficulty": 1, "interview": false, "concepts": ["top-k", "retrieval"]}}'::jsonb where id = 'm6-e4';
update exercises set content = '{"prompt": "This function normalizes a vector to have norm 1. It has two bugs: it divides by zero on the null vector, and it doesn''t actually normalize (it uses the sum instead of the Euclidean norm). Fix it: for the null vector, return the same vector.", "starter_code": "import math\n\ndef normalize(v):\n    n = sum(v)\n    return [x / n for x in v]", "tests": [{"call": "normalize([3, 4])", "expected": "[0.6, 0.8]"}, {"call": "normalize([0, 0])", "expected": "[0, 0]"}, {"call": "round(sum(x*x for x in normalize([1, 2, 2])), 6)", "expected": "1.0"}], "hints": ["The Euclidean norm is the square root of the sum of squares, not the sum of components.", "Check whether the norm is 0 before dividing.", "n = math.sqrt(sum(x*x for x in v)); if n == 0: return v"], "solution": "import math\n\ndef normalize(v):\n    n = math.sqrt(sum(x*x for x in v))\n    if n == 0:\n        return v\n    return [x / n for x in v]", "meta": {"difficulty": 2, "interview": false, "concepts": ["norm", "normalization"]}}'::jsonb where id = 'm6-e5';
update exercises set content = '{"prompt": "Write `chunk_text(text, size, overlap)` that splits the text into chunks of `size` words with `overlap` words shared between consecutive ones, and returns a list of strings. If the last chunk ends up with fewer than `overlap`+1 new words... don''t overthink it: just include every chunk the window generates, but don''t produce one that''s fully contained in the previous one.", "starter_code": "def chunk_text(text, size, overlap):\n    pass", "tests": [{"call": "chunk_text(''a b c d e f g'', 3, 1)", "expected": "[''a b c'', ''c d e'', ''e f g'']"}, {"call": "chunk_text(''a b c d e'', 4, 2)", "expected": "[''a b c d'', ''c d e'']"}, {"call": "chunk_text(''a b'', 5, 1)", "expected": "[''a b'']"}], "hints": ["Split into words with split() and advance by step = size - overlap.", "Generate windows words[i:i+size] and stop once i+size exceeds the length, except for the first one.", "for i in range(0, len(w), step): piece = w[i:i+size]; append it, and if i+size >= len(w): break"], "solution": "def chunk_text(text, size, overlap):\n    w = text.split()\n    step = size - overlap\n    out = []\n    for i in range(0, len(w), step):\n        out.append('' ''.join(w[i:i+size]))\n        if i + size >= len(w):\n            break\n    return out", "meta": {"difficulty": 2, "interview": true, "concepts": ["chunking"]}}'::jsonb where id = 'm6-e6';
update exercises set content = '{"prompt": "Implement a minimal lexical search index: `class LexicalIndex` with `add(id_, text)` and `search(query, k)` that scores each document by the number of query words (lowercased) it contains, and returns the k ids with the most matches, breaking ties by ascending id. It''s the basis of BM25 without the IDF weighting.", "starter_code": "class LexicalIndex:\n    def __init__(self):\n        self.docs = {}\n\n    def add(self, id_, text):\n        pass\n\n    def search(self, query, k):\n        pass", "tests": [{"call": "ix = LexicalIndex(); ix.add(''a'', ''Apple revenue grew''); ix.add(''b'', ''Nvidia revenue and margin''); ix.add(''c'', ''weather today''); ix.search(''revenue margin'', 2)", "expected": "[''b'', ''a'']"}, {"call": "ix = LexicalIndex(); ix.add(''x'', ''hello world''); ix.search(''goodbye'', 1)", "expected": "[''x'']"}], "hints": ["Store each document as a set of lowercased words.", "The score is len(query_words & doc_words).", "sorted(self.docs, key=lambda i: (-score(i), i))[:k]"], "solution": "class LexicalIndex:\n    def __init__(self):\n        self.docs = {}\n\n    def add(self, id_, text):\n        self.docs[id_] = set(text.lower().split())\n\n    def search(self, query, k):\n        q = set(query.lower().split())\n        score = lambda i: len(q & self.docs[i])\n        return sorted(self.docs, key=lambda i: (-score(i), i))[:k]", "meta": {"difficulty": 2, "interview": false, "concepts": ["lexical search", "BM25"]}}'::jsonb where id = 'm6-e7';
update exercises set content = '{"prompt": "Implement `rrf(lists, k=60)`: fusing rankings via Reciprocal Rank Fusion. It receives several ordered lists of ids (e.g. the lexical retriever''s and the vector one''s) and returns a single list of ids ordered by the sum of 1/(k + position), with position starting at 1. Ties: by ascending id.", "starter_code": "def rrf(lists, k=60):\n    pass", "tests": [{"call": "rrf([[''a'', ''b'', ''c''], [''b'', ''a'', ''d'']])", "expected": "[''a'', ''b'', ''c'', ''d'']"}, {"call": "rrf([[''x''], [''y'']])", "expected": "[''x'', ''y'']"}, {"call": "rrf([[''a'', ''b''], [''c'', ''b'']])", "expected": "[''b'', ''a'', ''c'']"}], "hints": ["Accumulate scores in a dict id -> float.", "For each list, enumerate(lst, start=1) gives you the position.", "sorted(scores, key=lambda i: (-scores[i], i))"], "solution": "def rrf(lists, k=60):\n    scores = {}\n    for lst in lists:\n        for pos, id_ in enumerate(lst, start=1):\n            scores[id_] = scores.get(id_, 0) + 1 / (k + pos)\n    return sorted(scores, key=lambda i: (-scores[i], i))", "meta": {"difficulty": 3, "interview": true, "concepts": ["RRF", "hybrid search"]}}'::jsonb where id = 'm6-e8';
update exercises set content = '{"prompt": "Implement `recall_at_k(relevant, retrieved, k)`: what fraction of the relevant ids appears among the first k retrieved. It''s the retrieval metric you measure BEFORE touching the LLM.", "starter_code": "def recall_at_k(relevant, retrieved, k):\n    pass", "tests": [{"call": "recall_at_k({''a'', ''b''}, [''b'', ''x'', ''a'', ''y''], 2)", "expected": "0.5"}, {"call": "recall_at_k({''a'', ''b''}, [''b'', ''x'', ''a'', ''y''], 3)", "expected": "1.0"}, {"call": "recall_at_k(set(), [''a''], 1)", "expected": "0.0"}], "hints": ["Cut the list to the first k and turn it into a set.", "Intersect with relevant, divided by len(relevant).", "If there are no relevant ids, return 0.0 to avoid dividing by zero."], "solution": "def recall_at_k(relevant, retrieved, k):\n    if not relevant:\n        return 0.0\n    top = set(retrieved[:k])\n    return len(top & set(relevant)) / len(relevant)", "meta": {"difficulty": 2, "interview": true, "concepts": ["recall@k", "retrieval evaluation"]}}'::jsonb where id = 'm6-e9';
update exercises set content = '{"isCode": false, "prompt": "Interview: in rag-finance you used embeddings with asymmetric task types (one for documents, another for queries). Why does that asymmetry exist, and what would happen if you embedded questions with the same mode as documents?", "modelAnswer": "A question and the passage that answers it have a different shape: the question is short and interrogative, the passage is long and declarative. Asymmetric models learn to project both into the same space so they end up close even without sharing words. Using the same mode for both degrades retrieval, especially for short questions, because the model treats them as if they were documents.", "meta": {"difficulty": 3, "interview": true, "concepts": ["asymmetric embeddings", "retrieval"]}}'::jsonb where id = 'm6-e10';
update exercises set content = '{"isCode": false, "prompt": "Interview: your RAGAS evaluation gave faithfulness 1.0, context recall 1.0, and answer relevancy 0.85. Explain what each one measures and why the last one can be lower even when the other two are perfect.", "modelAnswer": "Faithfulness: whether the answer is grounded in the retrieved context (no hallucination). Context recall: whether the retrieved context contains what''s needed to answer. Answer relevancy: whether the answer addresses exactly the question. It can be lower even with the other two perfect if the answer is correct and grounded but includes extra information, wanders off, or doesn''t get straight to the point.", "meta": {"difficulty": 3, "interview": true, "concepts": ["RAGAS", "metrics"]}}'::jsonb where id = 'm6-e11';
update exercises set content = '{"prompt": "Why are embeddings normalized before comparing them?", "answer": "So the dot product is equivalent to the cosine, and the comparison depends only on semantic direction, not magnitude.", "explanation": "With normalized vectors, dot(a, b) == cos(a, b), which also speeds up search.", "meta": {"difficulty": 1, "interview": true, "concepts": ["normalization"]}}'::jsonb where id = 'm6-e12';
update exercises set content = '{"prompt": "What''s hybrid search in RAG?", "answer": "Combining lexical retrieval (BM25, exact term matching) with vector retrieval (semantic) and fusing the rankings, typically with RRF.", "explanation": "Lexical wins on proper names, numbers, and acronyms; vector wins on paraphrasing. Together they cover each other''s gaps.", "meta": {"difficulty": 2, "interview": true, "concepts": ["hybrid search"]}}'::jsonb where id = 'm6-e13';
update exercises set content = '{"prompt": "What problem does overlap between chunks solve?", "answer": "That a sentence or idea that falls right at the cut between two chunks doesn''t end up split and unrecoverable by either one.", "explanation": "In exchange it duplicates some content in the index; 10-20% of the chunk size is a common value.", "meta": {"difficulty": 1, "interview": false, "concepts": ["chunking"]}}'::jsonb where id = 'm6-e14';
update exercises set content = '{"prompt": "What''s a reranker, and at what point in the pipeline does it act?", "answer": "A model (cross-encoder) that takes the question and passage together and returns a more precise relevance score. It acts after the initial retrieval, on the top-k, before passing context to the LLM.", "explanation": "It''s slower than an embedding, which is why it''s only applied to the few retrieved candidates.", "meta": {"difficulty": 2, "interview": true, "concepts": ["reranking"]}}'::jsonb where id = 'm6-e15';
update exercises set content = '{"isCode": false, "prompt": "Warm-up (M6): what does Reciprocal Rank Fusion do, and why is it used instead of summing the raw scores from two retrievers?", "modelAnswer": "It sums 1/(k + position) for each id in each ranking. It''s used because BM25 scores and cosine scores live on different scales and aren''t comparable; positions are.", "meta": {"difficulty": 1, "interview": false, "concepts": ["RRF"], "recuerda_de": "m6-rag-vectors"}}'::jsonb where id = 'm7-e1';
update exercises set content = '{"prompt": "Prompt templates. What does this print? Watch the double braces and the format method.", "code": "template = ''Answer in JSON with the key {{\"answer\"}}. Question: {question}''\nprint(template.format(question=''capital of France?''))\n\nsystem = \"You are an analyst. Context:\\n{ctx}\\n---\"\nprint(system.format(ctx=''\\n''.join([''[1] doc a'', ''[2] doc b''])))", "expected_output": "Answer in JSON with the key {\"answer\"}. Question: capital of France?\nYou are an analyst. Context:\n[1] doc a\n[2] doc b\n---", "explanation": "In format(), double braces {{ }} produce literal braces: essential when the prompt shows JSON examples. Retrieved context is injected with identifiers ([1], [2]) so the model can cite it.", "meta": {"difficulty": 2, "interview": false, "concepts": ["templates", "format", "escaped braces"]}}'::jsonb where id = 'm7-e2';
update exercises set content = '{"prompt": "Parsing a tool call. What does this print?", "code": "import json\n\nresponse = ''{\"tool\": \"search\", \"args\": {\"q\": \"nvidia margin\", \"k\": 3}}''\ntool_call = json.loads(response)\nprint(tool_call[''tool''])\nprint(sorted(tool_call[''args''].items()))\nprint(type(tool_call[''args''][''k'']).__name__)", "expected_output": "search\n[(''k'', 3), (''q'', ''nvidia margin'')]\nint", "explanation": "json.loads converts the text into a dict and respects the JSON types: 3 arrives as an int, not a str. That''s the reason for asking the model for JSON output instead of free text: the arguments already come typed.", "meta": {"difficulty": 1, "interview": false, "concepts": ["json.loads", "tool calling"]}}'::jsonb where id = 'm7-e3';
update exercises set content = '{"prompt": "Order the lines to build a dispatcher: given the tool''s name and its arguments, run the registered function or raise a clear error.", "lines": ["TOOLS = {}", "", "def register(fn):", "    TOOLS[fn.__name__] = fn", "    return fn", "", "def execute(call):", "    fn = TOOLS.get(call[''tool''])", "    if fn is None:", "        raise KeyError(f\"unknown tool: {call[''tool'']}\")", "    return fn(**call[''args''])"], "meta": {"difficulty": 2, "interview": true, "concepts": ["dispatcher", "tool registry"]}}'::jsonb where id = 'm7-e4';
update exercises set content = '{"prompt": "Models sometimes return JSON wrapped in a markdown code block (```json ... ```) with text around it. This function fails in that case. Fix it so it extracts the first valid JSON object between the first ''{'' and the last ''}''.", "starter_code": "import json\n\ndef extract_json(text):\n    return json.loads(text)", "tests": [{"call": "extract_json(''{\"a\": 1}'')", "expected": "{''a'': 1}"}, {"call": "extract_json(''Sure, here you go:\\n```json\\n{\"a\": 1, \"b\": [2]}\\n```'')", "expected": "{''a'': 1, ''b'': [2]}"}, {"call": "extract_json(''result: {\"ok\": true} done'')", "expected": "{''ok'': True}"}], "hints": ["Find the first opening brace with find(''{'') and the last closing one with rfind(''}'').", "Slice the text to that range (inclusive) before json.loads.", "return json.loads(text[text.find(''{''): text.rfind(''}'') + 1])"], "solution": "import json\n\ndef extract_json(text):\n    start = text.find(''{'')\n    end = text.rfind(''}'')\n    return json.loads(text[start:end + 1])", "meta": {"difficulty": 2, "interview": true, "concepts": ["structured output", "robust parsing"]}}'::jsonb where id = 'm7-e5';
update exercises set content = '{"prompt": "Write `schema(fn)` that generates a tool''s JSON description from a Python function: name, description (its docstring), and typed parameters, using the annotations. Map int->''integer'', str->''string'', float->''number'', bool->''boolean''. It''s what the SDK does for you; doing it by hand teaches you what the model actually sees.", "starter_code": "def schema(fn):\n    pass\n\ndef search(q: str, k: int) -> list:\n    \"\"\"Searches documents.\"\"\"\n    return []", "tests": [{"call": "schema(search)", "expected": "{''name'': ''search'', ''description'': ''Searches documents.'', ''parameters'': {''q'': ''string'', ''k'': ''integer''}}"}], "hints": ["fn.__name__, fn.__doc__, and fn.__annotations__ have everything you need.", "__annotations__ includes ''return'': exclude it.", "types = {int: ''integer'', str: ''string'', float: ''number'', bool: ''boolean''}"], "solution": "def schema(fn):\n    types = {int: ''integer'', str: ''string'', float: ''number'', bool: ''boolean''}\n    params = {n: types[t] for n, t in fn.__annotations__.items() if n != ''return''}\n    return {''name'': fn.__name__, ''description'': fn.__doc__, ''parameters'': params}\n\ndef search(q: str, k: int) -> list:\n    \"\"\"Searches documents.\"\"\"\n    return []", "meta": {"difficulty": 3, "interview": true, "concepts": ["tool schema", "introspection"]}}'::jsonb where id = 'm7-e6';
update exercises set content = '{"prompt": "Write `validate(output, fields)`: it receives a dict parsed from the model and a dict {field: type}; it returns a list of text errors (empty if everything''s fine). Errors: ''missing <field>'' and ''<field> should be <type>''. It''s the step before retrying with the error as feedback.", "starter_code": "def validate(output, fields):\n    pass", "tests": [{"call": "validate({''ticker'': ''NVDA'', ''score'': 0.8}, {''ticker'': str, ''score'': float})", "expected": "[]"}, {"call": "validate({''ticker'': ''NVDA''}, {''ticker'': str, ''score'': float})", "expected": "[''missing score'']"}, {"call": "validate({''ticker'': 7, ''score'': ''high''}, {''ticker'': str, ''score'': float})", "expected": "[''ticker should be str'', ''score should be float'']"}], "hints": ["Loop through fields.items() in order and accumulate messages.", "Check presence first with ''in'', then type with isinstance.", "expected_type.__name__ gives you ''str'', ''float''."], "solution": "def validate(output, fields):\n    errors = []\n    for field, expected_type in fields.items():\n        if field not in output:\n            errors.append(f''missing {field}'')\n        elif not isinstance(output[field], expected_type):\n            errors.append(f''{field} should be {expected_type.__name__}'')\n    return errors", "meta": {"difficulty": 2, "interview": true, "concepts": ["output validation", "structured output"]}}'::jsonb where id = 'm7-e7';
update exercises set content = '{"prompt": "Implement the retry loop: `with_retries(call_model, validate, attempts)`. `call_model(feedback)` simulates the model and returns a dict; `validate(dict)` returns a list of errors. Call with feedback=None the first time; if there are errors, call again passing the errors joined by ''; ''. Return the first valid dict, or None once attempts run out.", "starter_code": "def with_retries(call_model, validate, attempts):\n    pass\n\n# simulator: only gets it right once it receives feedback\ndef model(feedback):\n    return {''score'': 1.0} if feedback else {''score'': ''high''}\n\ndef val(d):\n    return [] if isinstance(d[''score''], float) else [''score should be float'']", "tests": [{"call": "with_retries(model, val, 3)", "expected": "{''score'': 1.0}"}, {"call": "with_retries(model, val, 1)", "expected": "None"}, {"call": "with_retries(lambda f: {''score'': 2.0}, val, 1)", "expected": "{''score'': 2.0}"}], "hints": ["A for _ in range(attempts) loop with a feedback variable starting at None.", "If validate returns an empty list, return the result; otherwise, update feedback.", "feedback = ''; ''.join(errors)"], "solution": "def with_retries(call_model, validate, attempts):\n    feedback = None\n    for _ in range(attempts):\n        r = call_model(feedback)\n        errors = validate(r)\n        if not errors:\n            return r\n        feedback = ''; ''.join(errors)\n    return None\n\n# simulator: only gets it right once it receives feedback\ndef model(feedback):\n    return {''score'': 1.0} if feedback else {''score'': ''high''}\n\ndef val(d):\n    return [] if isinstance(d[''score''], float) else [''score should be float'']", "meta": {"difficulty": 3, "interview": true, "concepts": ["retries with feedback", "self-correction"]}}'::jsonb where id = 'm7-e8';
update exercises set content = '{"prompt": "Match each prompting technique with the situation where it helps most.", "pairs": [{"term": "Few-shot", "definition": "You want a very specific format or style and it''s easier to show it than describe it"}, {"term": "Chain-of-thought", "definition": "The task needs several reasoning steps and the model fails by jumping straight to the answer"}, {"term": "System prompt with a role", "definition": "You need to fix tone, limits, and stable behavior across the whole conversation"}, {"term": "Structured output (JSON schema)", "definition": "The result will be consumed by code, not a person"}, {"term": "Tool calling", "definition": "The model needs data or actions it doesn''t have: search, calculate, query an API"}], "meta": {"difficulty": 2, "interview": true, "concepts": ["prompting techniques"]}}'::jsonb where id = 'm7-e9';
update exercises set content = '{"isCode": false, "prompt": "Interview: what''s the difference between asking the model to ''answer in JSON'' in the prompt versus using the API''s structured output / tool calling mode? When is the first one enough?", "modelAnswer": "Asking in the prompt is a suggestion: the model usually complies but might add text, wrap it in markdown, or break the schema, so you have to parse defensively and retry. Structured output from the API restricts generation to the schema and guarantees valid JSON. The first is enough for prototypes or when the cost of a failure is low; in production, with code consuming the output, the second is better.", "meta": {"difficulty": 2, "interview": true, "concepts": ["structured output"]}}'::jsonb where id = 'm7-e10';
update exercises set content = '{"isCode": false, "prompt": "Interview: in trade-signal-agent you used Gemini''s function calling for multi-step reasoning. Describe the full cycle of a tool call: who decides, who executes, and what goes back to the model.", "modelAnswer": "The model receives the tools'' schemas and decides whether it needs one, returning a name and arguments instead of text. My code (not the model) executes the actual function with those arguments and returns the result to the model as a tool-result message. The model reads it and decides: another call or a final answer. My code controls the loop, with a maximum number of steps.", "meta": {"difficulty": 3, "interview": true, "concepts": ["tool calling cycle", "agent"]}}'::jsonb where id = 'm7-e11';
update exercises set content = '{"prompt": "What''s temperature in an LLM, and what value would you use for data extraction?", "answer": "It controls the randomness of token sampling. For extraction or classification, 0 (or very low): you want the most probable, reproducible output.", "explanation": "High temperatures are for creativity; for tool calling and JSON, always low.", "meta": {"difficulty": 1, "interview": true, "concepts": ["temperature"]}}'::jsonb where id = 'm7-e12';
update exercises set content = '{"prompt": "What''s prompt injection?", "answer": "Untrusted text (a document, a webpage, a user) containing instructions that the model obeys as if they came from the developer.", "explanation": "It''s critical in RAG: retrieved context is data, not instructions, and the prompt must make that clear.", "meta": {"difficulty": 2, "interview": true, "concepts": ["security"]}}'::jsonb where id = 'm7-e13';
update exercises set content = '{"prompt": "Why are context passages numbered or labeled in a RAG prompt?", "answer": "So the model can cite the source of each claim ([1], [2]) and so you can verify faithfulness afterward.", "explanation": "Without identifiers there''s no way to trace which chunk supported which sentence.", "meta": {"difficulty": 1, "interview": false, "concepts": ["citations in RAG"]}}'::jsonb where id = 'm7-e14';
update exercises set content = '{"isCode": false, "prompt": "Warm-up (M7): why does an agent''s tool-calling loop need a maximum number of steps?", "modelAnswer": "Because the model can get stuck in a cycle (calling the same tool over and over, or never converging to an answer), and without a cap the cost and latency spiral. The limit turns a possible infinite loop into a controlled failure.", "meta": {"difficulty": 1, "interview": true, "concepts": ["max_steps"], "recuerda_de": "m7-prompting-tools"}}'::jsonb where id = 'm8-e1';
update exercises set content = '{"prompt": "Graph state with a reducer. What does this print? Pay attention to which fields get overwritten and which ones accumulate.", "code": "def apply(state, change, reducers):\n    updated = dict(state)\n    for k, v in change.items():\n        if k in reducers:\n            updated[k] = reducers[k](updated.get(k), v)\n        else:\n            updated[k] = v\n    return updated\n\nreducers = {''messages'': lambda old, new: (old or []) + new}\ns = {''step'': 0, ''messages'': [''hi'']}\ns = apply(s, {''step'': 1, ''messages'': [''searching'']}, reducers)\ns = apply(s, {''step'': 2, ''messages'': [''done'']}, reducers)\nprint(s[''step''], s[''messages''])", "expected_output": "2 [''hi'', ''searching'', ''done'']", "explanation": "A reducer defines how a state field gets combined: ''messages'' accumulates (like add_messages in LangGraph), while ''step'' with no reducer just gets replaced. It''s the difference between history and current state.", "meta": {"difficulty": 2, "interview": true, "concepts": ["reducers", "graph state"]}}'::jsonb where id = 'm8-e2';
update exercises set content = '{"prompt": "Order the lines to define the minimal structure of a graph: nodes (functions that receive state and return changes) and edges (from which node to which).", "lines": ["class Graph:", "    def __init__(self):", "        self.nodes = {}", "        self.edges = {}", "", "    def add_node(self, name, fn):", "        self.nodes[name] = fn", "", "    def add_edge(self, source, target):", "        self.edges[source] = target"], "meta": {"difficulty": 1, "interview": false, "concepts": ["graph", "nodes and edges"]}}'::jsonb where id = 'm8-e3';
update exercises set content = '{"prompt": "Step 1 of the mini-LangGraph. Complete `run(self, state, start)`: begin at the `start` node, run its function (which returns a dict of changes), update the state with it, and follow the edge until reaching ''END''. Return the final state.", "starter_code": "class Graph:\n    def __init__(self):\n        self.nodes = {}\n        self.edges = {}\n\n    def add_node(self, name, fn):\n        self.nodes[name] = fn\n\n    def add_edge(self, source, target):\n        self.edges[source] = target\n\n    def run(self, state, start):\n        pass\n\ng = Graph()\ng.add_node(''a'', lambda s: {''x'': s[''x''] + 1})\ng.add_node(''b'', lambda s: {''x'': s[''x''] * 10})\ng.add_edge(''a'', ''b'')\ng.add_edge(''b'', ''END'')", "tests": [{"call": "g.run({''x'': 1}, ''a'')", "expected": "{''x'': 20}"}, {"call": "g.run({''x'': 0}, ''b'')", "expected": "{''x'': 0}"}], "hints": ["A while loop: current != ''END''.", "change = self.nodes[current](state); state = {**state, **change}", "current = self.edges[current]"], "solution": "class Graph:\n    def __init__(self):\n        self.nodes = {}\n        self.edges = {}\n\n    def add_node(self, name, fn):\n        self.nodes[name] = fn\n\n    def add_edge(self, source, target):\n        self.edges[source] = target\n\n    def run(self, state, start):\n        current = start\n        while current != ''END'':\n            change = self.nodes[current](state)\n            state = {**state, **change}\n            current = self.edges[current]\n        return state\n\ng = Graph()\ng.add_node(''a'', lambda s: {''x'': s[''x''] + 1})\ng.add_node(''b'', lambda s: {''x'': s[''x''] * 10})\ng.add_edge(''a'', ''b'')\ng.add_edge(''b'', ''END'')", "meta": {"difficulty": 2, "interview": true, "concepts": ["graph execution", "state"]}}'::jsonb where id = 'm8-e4';
update exercises set content = '{"prompt": "Step 2: conditional edges. Add `add_conditional_edge(source, decide)` where `decide(state)` returns the name of the next node, and adapt `run` so that if the current node has a conditional edge, it uses it. Now you can make loops: an agent that keeps calling tools until it decides to stop.", "starter_code": "class Graph:\n    def __init__(self):\n        self.nodes = {}\n        self.edges = {}\n        self.conditionals = {}\n\n    def add_node(self, name, fn):\n        self.nodes[name] = fn\n\n    def add_edge(self, source, target):\n        self.edges[source] = target\n\n    def add_conditional_edge(self, source, decide):\n        pass\n\n    def run(self, state, start):\n        current = start\n        while current != ''END'':\n            change = self.nodes[current](state)\n            state = {**state, **change}\n            current = self.edges[current]\n        return state\n\ng = Graph()\ng.add_node(''count'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''count'', lambda s: ''END'' if s[''n''] >= 3 else ''count'')", "tests": [{"call": "g.run({''n'': 0}, ''count'')", "expected": "{''n'': 3}"}, {"call": "g.run({''n'': 5}, ''count'')", "expected": "{''n'': 6}"}], "hints": ["Store the decision function in self.conditionals[source].", "In run, after updating the state, check first whether current is in conditionals.", "current = self.conditionals[current](state) if current in self.conditionals else self.edges[current]"], "solution": "class Graph:\n    def __init__(self):\n        self.nodes = {}\n        self.edges = {}\n        self.conditionals = {}\n\n    def add_node(self, name, fn):\n        self.nodes[name] = fn\n\n    def add_edge(self, source, target):\n        self.edges[source] = target\n\n    def add_conditional_edge(self, source, decide):\n        self.conditionals[source] = decide\n\n    def run(self, state, start):\n        current = start\n        while current != ''END'':\n            change = self.nodes[current](state)\n            state = {**state, **change}\n            if current in self.conditionals:\n                current = self.conditionals[current](state)\n            else:\n                current = self.edges[current]\n        return state\n\ng = Graph()\ng.add_node(''count'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''count'', lambda s: ''END'' if s[''n''] >= 3 else ''count'')", "meta": {"difficulty": 3, "interview": true, "concepts": ["conditional edges", "loops"]}}'::jsonb where id = 'm8-e5';
update exercises set content = '{"prompt": "Step 3: safety. Add a `max_steps=10` parameter to `run`: if more nodes than that number run, raise RuntimeError(''max_steps''). Also record the list of visited nodes in `state[''trace'']` (create the list if it doesn''t exist). Don''t touch the marked block.", "starter_code": "class Graph:\n    def __init__(self):\n        self.nodes = {}\n        self.edges = {}\n        self.conditionals = {}\n\n    def add_node(self, name, fn):\n        self.nodes[name] = fn\n\n    def add_edge(self, source, target):\n        self.edges[source] = target\n\n    def add_conditional_edge(self, source, decide):\n        self.conditionals[source] = decide\n\n    def run(self, state, start, max_steps=10):\n        current = start\n        while current != ''END'':\n            change = self.nodes[current](state)\n            state = {**state, **change}\n            if current in self.conditionals:\n                current = self.conditionals[current](state)\n            else:\n                current = self.edges[current]\n        return state\n\n# --- do not touch ---\ng = Graph()\ng.add_node(''loop'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''loop'', lambda s: ''END'' if s[''n''] >= 2 else ''loop'')\n\ndef infinite_loop():\n    g2 = Graph()\n    g2.add_node(''x'', lambda s: {})\n    g2.add_edge(''x'', ''x'')\n    try:\n        g2.run({}, ''x'', max_steps=5)\n        return ''did not stop''\n    except RuntimeError as e:\n        return str(e)\n# --- end ---", "tests": [{"call": "g.run({''n'': 0}, ''loop'')[''trace'']", "expected": "[''loop'', ''loop'']"}, {"call": "infinite_loop()", "expected": "''max_steps''"}], "hints": ["Keep a step counter; increment it before running each node.", "if steps > max_steps: raise RuntimeError(''max_steps'')", "state = {**state, **change, ''trace'': state.get(''trace'', []) + [current]}"], "solution": "class Graph:\n    def __init__(self):\n        self.nodes = {}\n        self.edges = {}\n        self.conditionals = {}\n\n    def add_node(self, name, fn):\n        self.nodes[name] = fn\n\n    def add_edge(self, source, target):\n        self.edges[source] = target\n\n    def add_conditional_edge(self, source, decide):\n        self.conditionals[source] = decide\n\n    def run(self, state, start, max_steps=10):\n        current = start\n        steps = 0\n        while current != ''END'':\n            steps += 1\n            if steps > max_steps:\n                raise RuntimeError(''max_steps'')\n            change = self.nodes[current](state)\n            state = {**state, **change, ''trace'': state.get(''trace'', []) + [current]}\n            if current in self.conditionals:\n                current = self.conditionals[current](state)\n            else:\n                current = self.edges[current]\n        return state\n\n# --- do not touch ---\ng = Graph()\ng.add_node(''loop'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''loop'', lambda s: ''END'' if s[''n''] >= 2 else ''loop'')\n\ndef infinite_loop():\n    g2 = Graph()\n    g2.add_node(''x'', lambda s: {})\n    g2.add_edge(''x'', ''x'')\n    try:\n        g2.run({}, ''x'', max_steps=5)\n        return ''did not stop''\n    except RuntimeError as e:\n        return str(e)\n# --- end ---", "meta": {"difficulty": 3, "interview": true, "concepts": ["max_steps", "traceability"]}}'::jsonb where id = 'm8-e6';
update exercises set content = '{"prompt": "Step 4: a simulated ReAct agent on top of your Graph. You''re given a deterministic ''model'': `think(s)` returns {''action'': ''search''} if there''s no result yet, or {''action'': ''respond''} if there is. Write `build_agent()` that creates the graph with nodes ''think'', ''search'' (sets s[''result''] = ''data''), and ''respond'' (sets s[''response''] = ''Response: '' + s[''result'']), with the conditional edge from ''think'' based on s[''action''], ''search'' goes back to ''think'', and ''respond'' goes to ''END''. Don''t touch the marked block.", "starter_code": "# --- do not touch ---\nclass Graph:\n    def __init__(self):\n        self.nodes, self.edges, self.conditionals = {}, {}, {}\n    def add_node(self, n, fn): self.nodes[n] = fn\n    def add_edge(self, o, d): self.edges[o] = d\n    def add_conditional_edge(self, o, f): self.conditionals[o] = f\n    def run(self, state, start, max_steps=10):\n        current, steps = start, 0\n        while current != ''END'':\n            steps += 1\n            if steps > max_steps: raise RuntimeError(''max_steps'')\n            state = {**state, **self.nodes[current](state), ''trace'': state.get(''trace'', []) + [current]}\n            current = self.conditionals[current](state) if current in self.conditionals else self.edges[current]\n        return state\n\ndef think(s):\n    return {''action'': ''respond'' if ''result'' in s else ''search''}\n# --- end ---\n\ndef build_agent():\n    pass", "tests": [{"call": "r = build_agent().run({}, ''think''); r[''response'']", "expected": "''Response: data''"}, {"call": "build_agent().run({}, ''think'')[''trace'']", "expected": "[''think'', ''search'', ''think'', ''respond'']"}], "hints": ["Three nodes: think (given), search and respond as lambdas that return the state change.", "The conditional from think returns s[''action''] as-is: that''s the name of the next node.", "g.add_edge(''search'', ''think''); g.add_edge(''respond'', ''END'')"], "solution": "# --- do not touch ---\nclass Graph:\n    def __init__(self):\n        self.nodes, self.edges, self.conditionals = {}, {}, {}\n    def add_node(self, n, fn): self.nodes[n] = fn\n    def add_edge(self, o, d): self.edges[o] = d\n    def add_conditional_edge(self, o, f): self.conditionals[o] = f\n    def run(self, state, start, max_steps=10):\n        current, steps = start, 0\n        while current != ''END'':\n            steps += 1\n            if steps > max_steps: raise RuntimeError(''max_steps'')\n            state = {**state, **self.nodes[current](state), ''trace'': state.get(''trace'', []) + [current]}\n            current = self.conditionals[current](state) if current in self.conditionals else self.edges[current]\n        return state\n\ndef think(s):\n    return {''action'': ''respond'' if ''result'' in s else ''search''}\n# --- end ---\n\ndef build_agent():\n    g = Graph()\n    g.add_node(''think'', think)\n    g.add_node(''search'', lambda s: {''result'': ''data''})\n    g.add_node(''respond'', lambda s: {''response'': ''Response: '' + s[''result'']})\n    g.add_conditional_edge(''think'', lambda s: s[''action''])\n    g.add_edge(''search'', ''think'')\n    g.add_edge(''respond'', ''END'')\n    return g", "meta": {"difficulty": 3, "interview": true, "concepts": ["ReAct", "agent on a graph"]}}'::jsonb where id = 'm8-e7';
update exercises set content = '{"prompt": "Match what you built by hand with its equivalent in the real LangGraph API.", "pairs": [{"term": "Graph()", "definition": "StateGraph(TypedState)"}, {"term": "add_conditional_edge(source, decide)", "definition": "add_conditional_edges(source, decide)"}, {"term": "''END'' as a target", "definition": "The END constant imported from langgraph.graph"}, {"term": "reducer that concatenates messages", "definition": "Annotated[list, add_messages] in the state''s TypedDict"}, {"term": "max_steps", "definition": "recursion_limit in invoke''s configuration"}, {"term": "state[''trace'']", "definition": "A checkpointer (MemorySaver) that persists every step"}], "meta": {"difficulty": 2, "interview": true, "concepts": ["LangGraph API"]}}'::jsonb where id = 'm8-e8';
update exercises set content = '{"isCode": false, "prompt": "Interview: why model an agent as a state graph instead of a simple while loop with if/else? Give two concrete advantages.", "modelAnswer": "1) Each node is a pure function over the state: testable on its own and reusable. 2) The flow is explicit and inspectable: you can draw it, checkpoint after each node, resume, or insert a human-approval step between two nodes without rewriting the logic. A while loop with ifs mixes control flow with business logic and can''t be paused or audited.", "meta": {"difficulty": 3, "interview": true, "concepts": ["graph vs loop"]}}'::jsonb where id = 'm8-e9';
update exercises set content = '{"isCode": false, "prompt": "Interview: in trade-signal-agent, the backtest showed no advantage over a random baseline (4.77% vs 5.15%). Why did you document that result instead of hiding it, and what does that say about how you evaluate an agent?", "modelAnswer": "Because the value of the project is the methodology, not the number: comparing against a baseline with the same rules is what turns a demo into an evaluation. An honest negative result shows the evaluation isn''t rigged and that I can tell ''the agent works'' apart from ''the agent produces plausible-looking output.'' Hiding it would be exactly the mistake an employer wants to avoid.", "meta": {"difficulty": 3, "interview": true, "concepts": ["agent evaluation", "baseline"]}}'::jsonb where id = 'm8-e10';
update exercises set content = '{"prompt": "What''s the ReAct pattern?", "answer": "Reason + Act: the model alternates between reasoning about the state, choosing an action (a tool), observing the result, and repeating until it can answer.", "explanation": "It''s the think -> tool -> observation loop you implemented on top of the graph.", "meta": {"difficulty": 1, "interview": true, "concepts": ["ReAct"]}}'::jsonb where id = 'm8-e11';
update exercises set content = '{"prompt": "What''s a checkpointer in LangGraph, and what''s it for?", "answer": "A store that saves the graph''s state after every step, identified by a thread_id. It enables resuming, time-travel, and pausing for human intervention.", "explanation": "Without it, every invoke starts from scratch and there''s no memory between turns.", "meta": {"difficulty": 2, "interview": true, "concepts": ["checkpointer"]}}'::jsonb where id = 'm8-e12';
update exercises set content = '{"prompt": "What''s human-in-the-loop in an agent?", "answer": "Interrupting the graph before a sensitive action (sending, buying, deleting) so a person can approve or edit it, then resuming from the checkpoint.", "explanation": "In a trading agent, it''s the difference between suggesting a trade and executing it.", "meta": {"difficulty": 2, "interview": true, "concepts": ["human-in-the-loop"]}}'::jsonb where id = 'm8-e13';
update exercises set content = '{"prompt": "Order the phases of a RAG pipeline from start to finish, the way you''d actually build it (each line is a phase; the order matters).", "lines": ["# 1. Ingestion: load and clean the source documents", "# 2. Chunking: split into fragments with overlap and metadata", "# 3. Embeddings: vectorize each chunk (document mode)", "# 4. Indexing: store vectors + text + metadata in the vector DB", "# 5. Query: embed the question (query mode) and retrieve top-k", "# 6. Generation: build the prompt with cited context and call the LLM", "# 7. Evaluation: measure faithfulness, recall, and relevancy on a fixed dataset"], "meta": {"difficulty": 1, "interview": true, "concepts": ["RAG pipeline"]}}'::jsonb where id = 'm9-e1';
update exercises set content = '{"prompt": "Match each component of the capstone project with its responsibility. Each piece does one thing.", "pairs": [{"term": "ingest.py", "definition": "Turns raw sources into chunks with metadata and indexes them"}, {"term": "retrieve.py", "definition": "Given a question, returns the k most relevant passages (hybrid + rerank)"}, {"term": "generate.py", "definition": "Builds the prompt with cited context and calls the LLM"}, {"term": "agent.py", "definition": "Orchestrates tools and decides when to search, calculate, or respond"}, {"term": "eval.py", "definition": "Runs the evaluation dataset and reports metrics comparable across versions"}, {"term": "api.py (FastAPI)", "definition": "Exposes the system with auth, rate limiting, and structured logging"}], "meta": {"difficulty": 2, "interview": true, "concepts": ["architecture", "separation of concerns"]}}'::jsonb where id = 'm9-e2';
update exercises set content = '{"isCode": false, "prompt": "Design review 1: your system returns correct but slow answers (8 s). List, in the order you''d try them, three likely causes and how you''d measure each one.", "modelAnswer": "1) Retrieval: how long does the search take? Measure with per-phase timestamps. 2) Prompt size: too many chunks or chunks that are too long slow down generation; measure input tokens. 3) Sequential calls that could be concurrent (embeddings, reranker), or a server cold start. You measure by phase first; without that, any optimization is a shot in the dark.", "meta": {"difficulty": 3, "interview": true, "concepts": ["performance", "observability"]}}'::jsonb where id = 'm9-e3';
update exercises set content = '{"isCode": false, "prompt": "Design review 2: a user asks something that isn''t in the documents. What should the system do, and in which part of the pipeline would you implement it?", "modelAnswer": "It should say it doesn''t have the information, not make one up. Two layers: in retrieval, a minimum similarity threshold (if no chunk clears it, there''s no context); and in generation, an explicit instruction to answer only from the context and state when it isn''t enough. Verify it with negative cases in the evaluation dataset.", "meta": {"difficulty": 3, "interview": true, "concepts": ["abstention", "hallucinations"]}}'::jsonb where id = 'm9-e4';
update exercises set content = '{"isCode": false, "prompt": "Design review 3: you swap in a new embeddings model. What do you have to redo, what might break silently, and how would you detect it?", "modelAnswer": "You have to re-embed and reindex every chunk: two models'' vectors don''t live in the same space, so mixing them breaks retrieval without any error. It can also change the vector''s dimension. You detect it by running eval.py before and after: if context recall drops, something got mixed up or the model is worse for the domain.", "meta": {"difficulty": 3, "interview": true, "concepts": ["embeddings migration", "evaluation as a safety net"]}}'::jsonb where id = 'm9-e5';
update exercises set content = '{"isCode": false, "prompt": "Design review 4 (the pitch): you have 60 seconds in an interview to explain the capstone project. Write it: problem, architecture in one sentence, the most interesting technical decision, and the measured result.", "modelAnswer": "Example structure: ''It''s a financial-analysis assistant over 10-K reports. A hybrid RAG pipeline with reranking, an agent that decides when to search or calculate, and a deployed FastAPI API. The most interesting decision was evaluating against a baseline and publishing that the first version didn''t beat it; that led me to change the chunking and raise context recall from 0.7 to 1.0. Everything is measured and reproducible in the repo.''", "meta": {"difficulty": 3, "interview": true, "concepts": ["technical communication", "pitch"]}}'::jsonb where id = 'm9-e6';
update exercises set content = '{"prompt": "What should an AI project''s README contain for an interviewer to take it seriously?", "answer": "The problem, architecture with a diagram, technical decisions and why, evaluation results with numbers, how to reproduce them, and known limitations.", "explanation": "Limitations and numbers are what set a portfolio project apart from a copied tutorial.", "meta": {"difficulty": 1, "interview": true, "concepts": ["README"]}}'::jsonb where id = 'm9-e7';
update exercises set content = '{"prompt": "Why is a fixed, versioned evaluation dataset essential?", "answer": "Because without it you can''t tell whether a change (prompt, chunking, model) made the system better or worse: numbers are only comparable over the same cases.", "explanation": "It''s the equivalent of the test suite in classic software.", "meta": {"difficulty": 1, "interview": true, "concepts": ["evaluation dataset"]}}'::jsonb where id = 'm9-e8';

